import os, sys, time
# When lua does io.popen, it forks shell (dash) which then execs python. So ppid of python is dash, not lua. We need to get lua pid via traversing parents.

def get_pid_chain():
    pid = os.getpid()
    chain=[]
    while True:
        try:
            with open(f"/proc/{pid}/status") as f:
                for line in f:
                    if line.startswith("PPid:"):
                        ppid = int(line.split()[1])
                        chain.append((pid, ppid))
                        pid = ppid
                        break
                else:
                    break
        except:
            break
        if pid==1:
            break
    return chain

chain = get_pid_chain()
print("chain", chain)

# Find process whose exe is /workspace/executable
for pid,_ in chain:
    try:
        exe = os.readlink(f"/proc/{pid}/exe")
        print(f"pid {pid} exe {exe}")
        if "executable" in exe:
            # Found lua process
            mem_path = f"/proc/{pid}/mem"
            maps_path = f"/proc/{pid}/maps"
            print(f"Found lua pid {pid}, reading maps")
            maps = open(maps_path).read()
            print(maps[:2000])
            for line in maps.splitlines():
                if "executable" in line:
                    print(line)
                    # Try dump
                    if "r--" in line or "r-x" in line:
                        se = line.split()[0]
                        s,e = se.split('-')
                        start = int(s,16)
                        end = int(e,16)
                        # Only dump first 16k for test
                        fd = os.open(mem_path, os.O_RDONLY)
                        try:
                            data = os.pread(fd, 100, start)
                            print(f"read from {hex(start)}: {data[:20]}")
                        except Exception as ex:
                            print("pread fail", ex)
                        os.close(fd)
            break
    except Exception as ex:
        print(f"pid {pid} fail {ex}")

